+	if err != nil {
+		return nil, err
+	}
+	iterator := assignmentDoc.Collection(roleAssignmentAudit).Documents(ctx)
+	defer iterator.Stop()
+	audits := make([]domain.RoleAssignmentAudit, 0)
+	for {
+		snapshot, nextErr := iterator.Next()
+		if errors.Is(nextErr, iterator.Done) {
+			break
+		}
